TP.register({id:"lp7-g1",lp:7,grade:"1",mode:"curriculum",checks:6,nextGrade:"2nd grade",build(E){const F=E.F;const HOUSE="cabin",TREE="tree",FLOWER="purpleFlower",SUNFLOWER="sunflower",HERB="herb",LEAF="leaf",SPROUT="sprout",BEE="bee",BUTTERFLY="butterfly",DUCK="duck",DOG="dog",CAT="cat",RABBIT="rabbit",BIRD="bluebird",SUN="sun",SOUP="soup",BREAD="bread",MILK="milk",BOOK="books",BOX="box",BOOT="boot",HAT="topHat",PACK="pack",EAR="ear",HAND="hand",HANDS="hands";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",PINK="#F4899E",ROSE="#F6B3D0",PURPLE="#C9A6EC",PEACH="#F7C07A",CORALH="#EE8E86",BRASS="#D9A066",CREAM="#FBF1E4",SKY="#FBD9E4",SKY_L="#FDEEF3",GRASS="#C6E8AE",GRASS_D="#A9D790",STEM="#7FC08A",LEAFA="#A8D49A",LEAFB="#BFE3A8",LEAFE="#4E7A46";function heartShape(x,y,s,c){const k=s/60,c0=c||PINK;return`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})"><path d="M0 20 C-25 3 -30 -13 -18 -21 C-9 -27 -2 -22 0 -16 C2 -22 9 -27 18 -21 C30 -13 25 3 0 20 Z" fill="${c0}" stroke="${INK}" stroke-width="2.6" stroke-linejoin="round"/>`+at(0,-5,.5,K_FACE(0,0,12,4))+`</g>`}const heartSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*.85)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a paper heart">${heartShape(w/2,w*.51,w*.92,c)}</svg>`;const GARDEN_DAY="Our street has a garden. It is at the end. Every family takes care of one row. My job is the row of beans. On Saturday I pull the weeds. I fill the can at the tap. The woman next door is away. She is gone this week. So I water her row too. She did the same for me. That was last month. When I am done I sit down. The bench is in the shade. I watch the bees go by. Then I hang up a heart. It goes on the string.";const SHED="Ines could not reach the top shelf in the tool shed. The trowel she wanted was up there, right at the top, next to a ball of string. She stretched up on her toes, but her fingers only brushed the edge. Dev saw her trying. He brought the step stool over from behind the door and held it steady while she climbed. At last Ines got her trowel. Then she reached back up and got one down for Dev too.";const BARN="Long before there were trucks and cranes, a family who needed a barn could not build one alone. So the neighbors picked a day and all came at once. Some cut the timber. Some fitted the joints together on the ground. Then, all together, they lifted whole walls up on end with long poles. A barn that would have taken one family a whole year went up in two or three days. The families who came were not paid. They came because their own turn would come, and when it did, everybody would show up for them.";const TOOLS="The tool shed by the gate belongs to everybody on the street. A list is taped inside the door, and you sign your name when you borrow something. The rule is that a tool goes back the same day, clean and dry. Last spring a rake went missing for a month, so the list now has a second line for the day you bring it back.";const WORDS=["shed","thank","grow","fuzz","vine","right","sprout","corn","planted","sunflower","garden","blean"];function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}function heartRow(n){const w=620,h=150,x0=40,x1=w-40,sag=22,ry=x=>{const t=(x-x0)/(x1-x0);return 44+4*sag*t*(1-t)};let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;b+=`<path d="M${x0} 44 Q${(x0+x1)/2} ${44+2*sag} ${x1} 44" fill="none" stroke="${BRASS}" stroke-width="5" stroke-linecap="round"/>`;const cols=[PINK,ROSE,PURPLE,PEACH,CORALH];for(let i=0;i<n;i++){const x=x0+(i+.5)*(x1-x0)/n;b+=heartShape(x,ry(x)+34,48,cols[i%5])}return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A string across the garden gate with ${n} paper hearts hanging from it">${b}</svg>`}function heartGrid(n,per){const cell=74,rows=Math.ceil(n/per),w=per*cell+20,h=rows*cell+24;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const cols=[PINK,PEACH];for(let i=0;i<n;i++)b+=heartShape(10+i%per*cell+cell/2,16+Math.floor(i/per)*cell+cell/2,58,cols[Math.floor(i/per)%2]);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,620)}" role="img" aria-label="${n} paper hearts">${b}</svg>`}const CLOCKS=[["A",3,0],["B",7,30],["C",11,0],["D",1,30]];function clockRow(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">`+CLOCKS.map(c=>`<div>${F.clock(c[1],c[2],200)}<p class="fig-label">Clock ${c[0]}</p></div>`).join("")+`</div>`}function shedList(){return F.table(["What is in the shed","What it is for"],[[`${heartSvg(34,PINK)} a paper heart`,"to say thank you on the string"],[`${ic(BOOT,30)} a rain boot`,"to keep your feet dry in the mud"],[`${ic(BOOK,30)} a notebook`,"to write down what you planted"],[`${ic(SOUP,30)} a pot of soup`,"to take to a neighbor who is sick"]],{caption:"Garden Shed List"})}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const WDIR="Write on your paper. When you finish, hold it up and read it to your teacher.";const BOOKBOX="Our street has a little book box on a post. Anyone may open it. If you see a book you want to read, you take it, and you do not pay. When you are done, you bring the book back. Or you can put in a book of your own for someone else to enjoy. The box is open all day, so you can visit it any time.";const boxBg=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const flab=(x,y,t,sz)=>`<text x="${x}" y="${y}" font-size="${sz||24}" font-family="Andika,sans-serif" font-weight="700" text-anchor="middle" fill="var(--muted)">${t}</text>`;function unitsFig(){const w=680,h=316,u=72,x0=60;const card=(x,y)=>`<rect x="${x}" y="${y}" width="${u}" height="${u}" fill="${CREAM}" stroke="${INK}" stroke-width="3"/>`+heartShape(x+u/2,y+u/2,42,PEACH);let b=boxBg(w,h);b+=`<rect x="${x0}" y="30" width="${6*u}" height="22" rx="10" fill="${PINK}" stroke="${INK}" stroke-width="3"/>`;for(let i=0;i<6;i++)b+=card(x0+i*u,62);b+=flab(x0+3*u,158,"the ribbon");b+=`<rect x="${x0}" y="176" width="${4*u}" height="18" rx="9" fill="${BRASS}" stroke="${INK}" stroke-width="3"/>`;for(let i=0;i<4;i++)b+=card(x0+i*u,204);b+=flab(x0+2*u,300,"the trowel handle");return`<svg viewBox="0 0 ${w} ${h}" width="620" role="img" aria-label="A pink ribbon with 6 same-size square heart cards laid edge to edge under it, and a shorter brown trowel handle with 4 of the same cards laid edge to edge under it.">${b}</svg>`}function shareFig(){const w=720,h=250,st=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;let b=boxBg(w,h);b+=`<circle cx="118" cy="110" r="72" fill="${PEACH}" ${st}/><path d="M118 38 V182" stroke="${INK}" stroke-width="4"/>`+flab(118,216,"A");b+=`<rect x="276" y="52" width="200" height="116" fill="${GRASS_D}" ${st}/><path d="M326 52 V168 M376 52 V168 M426 52 V168" stroke="${INK}" stroke-width="4"/>`+flab(376,216,"B");b+=`<circle cx="602" cy="110" r="72" fill="${PEACH}" ${st}/><path d="M558 42 V178" stroke="${INK}" stroke-width="4"/>`+flab(602,216,"C");return`<svg viewBox="0 0 ${w} ${h}" width="660" role="img" aria-label="A is a round loaf cut by one line down the middle into two pieces the same size. B is a rectangle garden bed cut by three lines into four strips the same size. C is a round loaf cut by one line off to the left, so one piece is much smaller than the other.">${b}</svg>`}const STOPS=[{id:1,title:"Garden Sound Check",short:"Sounds",parts:[{std:["RF.1.2"],n:6,dur:70,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)} ${ic(BEE,96)}</p><p class="big" style="text-align:center">Listen. Then say it.</p>`,key:["Blend these sounds: /h/ /e/ /l/ /p/ (help)","Blend these sounds: /sh/ /e/ /d/ (shed)","Clap the word parts in garden. How many parts? (2 parts: gar and den)","What is the last sound in seed? (/d/)","Say all the sounds in kind. (/k/ /ie/ /n/ /d/, four sounds)","Which word has a long vowel sound: seed or set? (seed)"],desc:"blending, segmenting, and isolating sounds, counting syllables, and telling long from short vowels in spoken words"}]},{id:2,title:"Garden Words",short:"Garden Words",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:85,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. blean is a silly word: listen for the ea team saying long e.","Watch for: sh digraph (shed), th digraph plus nk (thank), blend plus a vowel team (grow), double letters (fuzz), final e (vine), igh (right), a three-letter blend plus the ou diphthong (sprout), r-controlled or (corn), the -ed ending said as /id/ (planted), a compound word with three syllables (sunflower), two syllables with r-controlled ar (garden)."],desc:"reading words with digraphs, blends, final e, vowel teams, r-controlled vowels, endings, and two or more syllables"}]},{id:3,title:"Count the Hearts",short:"To 120",parts:[{std:["1.NBT.A.1"],n:4,dur:85,dir:"Count and read out loud. Write your numbers on your paper and hold it up.",html:()=>`<p class="small" style="text-align:center">The garden club counts every paper heart before it goes up on the string.</p>`,qs:["Count out loud from 92 to 108.","Read these numbers out loud: 73, 100, 116.","Write the number one hundred nine.","Count the hearts in the picture. Write the number that tells how many."],fig2:()=>F.row(heartGrid(18,9)),key:["92, 93, 94 ... 99, 100, 101 ... 107, 108. Watch the jump past 99","Seventy-three, one hundred, one hundred sixteen","109, not 1009","18"],desc:"counting, reading, and writing numerals to 120 and counting objects"}]},{id:4,title:"Our Garden Day",short:"Garden Read",parts:[{std:["RF.1.4"],kind:"read",n:82,label:"words read correctly",dur:90,dir:"Look at the three pictures. Then read the story out loud in your best reading voice.",html:()=>`${F.row(F.pic(SPROUT,"a bean sprout","3.6rem"),F.pic(BOOT,"a garden boot","3.6rem"),F.pic(BEE,"the bees","3.6rem"))}${story("Our Garden Day",GARDEN_DAY)}`,key:["82 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Point to the three pictures first so beans, boots, and bees are clear before the student reads.","Note pace, expression, and whether the student rereads to fix a mistake.","Quick check after reading: Why does the reader water the row next door? (the woman who lives there is away this week, and she did the same for the reader last month)"],desc:"an 82-word shared-garden story read aloud"}]},{id:5,title:"Kindness Problems",short:"Problems",parts:[{std:["1.OA.A.1"],dur:125,dir:"Listen to each story problem. You can draw on your paper. Say your answer.",html:()=>`<div class="figure">${heartRow(7)}</div><p class="small" style="text-align:center">The club hangs a paper heart on the string for every kind thing somebody does.</p>`,qs:["On Monday 8 hearts went up and on Tuesday 7 more went up. How many hearts is that in all?","There were 16 hearts on the string. The wind blew 9 of them off. How many are still up?","Luz picked 6 beans. Omar picked 14 beans. How many more beans did Omar pick?","There are 17 hearts on the string. 8 of them are pink. The rest are purple. How many are purple?","Some hearts were already on the string. Then 6 more went up. Now there are 15. How many were on the string at the start? Write a number sentence with a box and hold it up."],key:["15 hearts (8 + 7 = 15)","7 hearts (16 - 9 = 7)","8 more beans (14 - 6 = 8 or 6 + 8 = 14)","9 purple (17 - 8 = 9 or 8 + 9 = 17)","9 hearts. Writes a box plus 6 equals 15, or 15 - 6 equals a box"],desc:"addition and subtraction word problems within 20, with the unknown in different places"}]},{id:6,title:"The Top Shelf",short:"Shelf",parts:[{std:["RL.1.1"],dur:85,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>story("The Top Shelf",SHED),qs:["What could Ines not reach?","What did she want from up there?","Who helped her, and what did he bring?","What did Ines do after she got her trowel?","Ask me a question about the story."],key:["The top shelf in the tool shed","The trowel, which was next to a ball of string","Dev. He brought the step stool from behind the door and held it steady","She reached back up and got a trowel down for Dev too","Asks a real question about the story, such as: Why was the shelf so high? If stuck, say: Start with who, what, or where."],desc:"asking and answering key detail questions about a story the student read"}]},{id:7,title:"Strings of Ten",short:"Tens Ones",parts:[{std:["1.NBT.B.2"],n:5,dur:95,dir:"Look at the blocks. Answer out loud.",html:()=>`<p class="small" style="text-align:center">A full string holds 10 paper hearts. A long block stands for one full string of ten. A small cube stands for one loose heart.</p>`,fig:()=>F.row(F.tens(4,6)),qs:["Look at the picture. How many full strings of ten do you see, and how many loose hearts? What number is that?","In the number 28, what does the 2 stand for? What does the 8 stand for?","The club has 70 hearts. How many full strings of ten is that? How many loose hearts are left over?","Which is more, 5 strings of ten or 40 hearts? How do you know?","The number 16 is one ten and six ones. Say a number that is one ten and three ones."],key:["4 strings of ten and 6 loose. That is 46","The 2 stands for two tens, which is twenty hearts. The 8 stands for eight ones","7 strings of ten, and 0 loose hearts left over","5 strings of ten. 5 tens is 50, and 50 is more than 40","13"],desc:"place value in two-digit numbers (bundles of ten and leftover ones)"}]},{id:8,title:"Add Up the Rows",short:"Add Up",parts:[{std:["1.NBT.C.4"],n:5,dur:95,dir:"Solve each one on your paper. Say your answer and tell how you got it.",html:()=>`<p class="big" style="margin-top:0">The club counts the seeds that go in each row.</p>`,qs:["The bean row has 34 seeds in it. The club plants 5 more. How many now?","The corn row has 52 seeds in it. The club plants 30 more. How many now?","The pea row has 27 seeds in it. The club plants 8 more. How many now?","The herb row has 61 seeds in it. The club plants 20 more. How many now?","The flower row has 46 seeds in it. The club plants 9 more. How many now?"],key:["39 (34 + 5 = 39. Only the ones change)","82 (52 + 30 = 82. Adding tens to tens: 5 tens and 3 tens is 8 tens)","35 (27 + 8 = 35. 7 + 8 is 15, so a new ten is made)","81 (61 + 20 = 81)","55 (46 + 9 = 55. 6 + 9 is 15, so a new ten is made)"],desc:"adding within 100 (a two-digit number plus a one-digit number and plus a multiple of ten)"}]},{id:9,title:"The Clock in the Shed",short:"Clocks",parts:[{std:["1.MD.B.3"],n:6,dur:95,dir:"Look at each clock. Say the time out loud. Then write the last two answers on your paper.",html:()=>`<p class="big" style="margin-top:0">The clock in the tool shed tells the club when to start and when to stop.</p>`,fig:()=>clockRow(),qs:["What time does Clock A say?","What time does Clock B say?","What time does Clock C say?","What time does Clock D say?","Which hand tells you the hour, the short one or the long one?","The club meets at half past four. Write that time on your paper."],key:["3:00, said as three o'clock. The long hand is on the 12 and the short hand is on the 3","7:30, said as seven thirty or half past seven. The long hand is on the 6. Watch for a student who says eight thirty, because the short hand has moved halfway toward the 8","11:00, said as eleven o'clock","1:30, said as one thirty or half past one. Watch for two thirty here for the same reason","The short hand. The long hand tells the minutes","4:30. Writing it as 4:30 is what to look for. Half past four is the same time said a different way"],desc:"telling and writing time to the hour and the half hour on an analog clock"}]},{id:10,title:"Garden Sign Check",short:"Signs",parts:[{title:"Sentence Spotter",std:["RF.1.1"],dur:50,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">We water the rows. Can you hold this?</p>`,qs:["How many sentences do you see? How can you tell?","Read the first word of the second sentence. What kind of letter does it start with?","What is the mark at the end of the second sentence called? What does it tell you?","Spot the mistake. Look at the words in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">the beans are tall</p></div>`,key:["2 sentences. Each one starts with a capital letter and ends with an end mark","The word is Can. It starts with a capital, or uppercase, C","A question mark. It tells you the sentence asks something","The first word needs a capital letter, and the sentence needs a period at the end"],desc:"finding sentences by their first word, capital letter, and end mark"},{title:"Garden Fix It",std:["L.1.1"],dur:70,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["Today we share the tools. Yesterday we ____.","One bench, two ____.","Which sounds right? The bees buzzes in the row. Or: The bees buzz in the row.","Join these two sentences with the word <b>and</b>: The sun is hot. The row is dry.","Add a word that tells more about the gate: The ____ gate opens slowly.","Finish it so it tells where: The watering can sits ____ the shed."],key:["shared","benches","The second one. More than one bee goes with the verb buzz","The sun is hot, and the row is dry","Any describing word that fits, such as old, wooden, green, or little","Any word that tells where and fits, such as in, by, near, behind, or beside"],desc:"spoken grammar items (past tense, plural nouns, subject and verb match, joining two sentences, describing words, place words)"}]},{id:11,title:"Barn Raising Radio",short:"Listen",parts:[{title:"Listen Up",std:["SL.1.2"],n:4,dur:65,read:BARN,dir:"Listen carefully. Your teacher will read about how neighbors helped each other long ago. Then answer out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)}</p><p class="big" style="text-align:center">Listen.</p>`,key:["Ask: What could one family not do alone? (build a barn)","Ask: What did the neighbors do with the long poles? (they lifted whole walls up on end, all together)","Ask: Why did the families come if nobody paid them? (because their own turn would come, and then everybody would show up for them)","Say: Ask me one question about barn raising. (asks 1 question that is about what was read and starts with a question word, such as: How many people came?)"],desc:"asking and answering questions about a text read aloud"},{title:"Tell Me About It",std:["SL.1.4"],n:3,label:"checks met",dur:60,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about a time somebody gave you a hand with something.</p><ul class="qlist" style="margin-top:14px"><li>What were you trying to do?</li><li>What did the person do?</li><li>How did you feel after?</li></ul>`,key:["Names what they were trying to do and gives 2 or more details about it (SL.1.4)","Says what the other person did, with 1 or more details, all about this one time (SL.1.4)","Says how they felt after, in at least 1 complete sentence (SL.1.4)"],desc:"describing an event with relevant details"}]},{id:12,title:"Use the Shed List",short:"Shed List",parts:[{std:["W.1.8"],n:3,label:"checks met",dur:80,dir:"Look at the chart. Write 1 sentence on your paper and hold it up.",html:()=>`<p class="big">A neighbor on your row is home sick in bed. You want to bring her something from the shed. What will you take? Use the chart.</p>`,fig:()=>shedList(),key:["Finds the answer in the chart. Your help is fine: read the two columns out loud and point to the row headings","Writes a sentence drawn from the chart, such as: I will take the pot of soup","The answer fits the question. It names the one item on the list that is for a neighbor who is sick"],desc:"using a provided chart to answer a question in writing"}]},{id:13,title:"Garden Journal",short:"Write",parts:[{wk:"facts",alt:{group:"write",label:"How to Help",icon:"📖",hint:"Name it and give some facts"},std:["W.1.2"],n:4,label:"checks met",dur:170,dir:WDIR,html:()=>`<p class="big">Pick one job that helps other people: watering a neighbor's row, walking a dog, setting the table, or feeding a pet. Name the job. Then write some facts about it: what you do, what you need, and why it helps.</p><div class="figure">${F.pic(SPROUT,"a bean sprout","3.4rem")}${F.pic(DOG,"a dog","3.4rem")}${F.pic(SOUP,"a bowl for the table","3.4rem")}</div>${TWO}`,key:["Names the topic: the one job the student picked (W.1.2)","Supplies at least two facts about the job, such as what you do or what you need (W.1.2)","The facts are about the named job and are true (W.1.2)","Gives some sense of closure, such as: That is how you ____, or That is why it helps (W.1.2)","Only the challenge the student picks gets rated here. If your curriculum lists both W.1.2 and W.1.3, the other prompt works as a follow-up on paper another day, and the record sheet shows the unpicked one as unrated."],desc:"an informative piece naming a helping job and giving facts about it"},{wk:"story",alt:{group:"write",label:"A Day I Helped",icon:"✏",hint:"Tell two things that happened, in order"},std:["W.1.3"],n:4,label:"checks met",dur:170,dir:WDIR,html:()=>`<p class="big">Write about a day you helped somebody, or a day somebody helped you. Tell two things that happened, in order. Use the words first and then. End by telling how it felt.</p><div class="figure">${F.pic(HANDS,"two hands","3.4rem")}${F.pic(BOX,"a box to carry","3.4rem")}${heartSvg(54,PINK)}</div>${TWO}`,key:["Tells about two or more things that happened, in an order that makes sense (W.1.3)","Includes some detail about what happened, not just a list (W.1.3)","Uses a time word such as first, then, next, or after that to signal the order (W.1.3)","Ends with a sense of closure, such as how it felt or what happened last (W.1.3)","Only the challenge the student picks gets rated here. If your curriculum lists both W.1.2 and W.1.3, the other prompt works as a follow-up on paper another day, and the record sheet shows the unpicked one as unrated."],desc:"a narrative about a day the student helped or was helped, told in order"}]},{id:14,title:"The Book Box",short:"Book Box",parts:[{std:["RI.1.1"],n:3,dur:65,dir:"Read the facts out loud. Then answer out loud.",html:()=>`<p class="big" style="text-align:center;margin:0 0 6px">The Book Box</p><p class="passage">${BOOKBOX}</p>`,qs:["What is inside the book box?","What do you do when you are done with a book?","Now you ask me a question about the book box."],key:["Books","You bring it back, or you put in a book of your own. Either half counts","Asks a real question about the box, such as: Who built it? or What if it rains? Telling a fact instead of asking does not count"],desc:"asking and answering key detail questions about an informational text the student read"}]},{id:15,title:"What I Think",short:"Opinion",parts:[{wk:"opinion",std:["W.1.1"],n:3,label:"checks met",dur:75,dir:WDIR,html:()=>`<p class="big">A new family just moved in. They came onto your street. What is the better way? You want to make them feel welcome. You could take them some soup. Take a pot of it. You could walk them around. You could show them the garden. Write what you think and why.</p><div class="figure">${F.pic(SOUP,"a pot of soup","3.4rem")}${F.pic(SPROUT,"the garden","3.4rem")}</div><ul class="qlist" style="margin-top:14px"><li>Write 2 sentences.</li></ul>`,key:["Names what the choice is about, the soup or the garden walk, so a reader who did not hear the question still knows (W.1.1)","States an opinion: which one the student would pick (W.1.1)","Supplies a reason for the pick, such as: soup is warm when you are tired from moving (W.1.1)","A closing line such as That is what I think is a plus at this length, not a requirement. Note it if it is there.","Two sentences is the whole job here. Do not ask for more."],desc:"a short opinion piece naming the choice, stating an opinion, and giving a reason"}]},{id:16,title:"Hearts Both Ways",short:"Both Ways",parts:[{title:"Turn It Around",std:["1.OA.B.3"],n:3,dur:60,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="big">The club hangs hearts on two strings.</p>`,qs:["You know 8 + 5 = 13. So what is 5 + 8? How do you know?","Is 7 + 6 the same as 6 + 7? How do you know?","To add 4 + 7 + 3, which two would you add first, and why?"],key:["13. The same two parts, just said in the other order, so the total does not change","Yes, both make 13. Same parts, other order. Look for the reason, not only the answer","7 and 3 first, because they make 10. Then 10 + 4 = 14. Adding 4 + 7 first and getting 14 is still correct, but the ten-maker is the strategy to look for"],desc:"using the order of addends and making a ten as strategies to add"},{title:"Count On, Count Back",std:["1.OA.C.5"],n:3,dur:55,dir:"Answer out loud. You may count on your fingers.",qs:["There are 9 hearts on the string. 3 more go up. Count on from 9 to find how many. Say the numbers you count.","There are 14 hearts on the string. 2 blow off. Count back to find how many are left.","Which is quicker for 2 + 8: counting on from 2, or counting on from 8? Why?"],key:["12. Says 10, 11, 12, starting from 9 and not from 1","12. Says 13, 12","From 8, because then you only count on 2 more. Counting on from the bigger number is the point here"],desc:"counting on to add and counting back to subtract"}]},{id:17,title:"Tens Off the String",short:"Tens Off",parts:[{std:["1.NBT.C.6"],n:3,dur:55,dir:"Solve each one on your paper. Say your answer and tell how you got it.",html:()=>`<p class="small" style="text-align:center">A full string holds 10 paper hearts.</p>`,fig:()=>F.row(F.tens(7,0)),qs:["The picture shows the hearts on the gate. The club takes 3 whole strings down. How many hearts are left?","90 - 50","60 - 60"],key:["40 hearts. 7 strings of ten take away 3 strings of ten leaves 4 strings of ten, which is 70 - 30 = 40","40. 9 tens take away 5 tens is 4 tens","0. 6 tens take away 6 tens leaves nothing","Listen for tens language. An answer found by counting every single heart is correct but not yet place value, so write that down"],desc:"subtracting a multiple of ten from a multiple of ten using tens"}]},{id:18,title:"How Many Hearts Long",short:"Measure",parts:[{std:["1.MD.A.2"],n:3,dur:60,dir:"Look at the picture. Answer out loud.",fig:()=>F.row(unitsFig()),qs:["The heart cards are all the same size. How many cards long is the ribbon?","How many cards long is the trowel handle?","If you left gaps between the cards, would you get the right length? Why not?"],key:["6 cards long","4 cards long","No. The cards have to touch edge to edge, with no gaps and no overlaps, or part of the ribbon does not get measured and the number comes out too small"],desc:"measuring length as a whole number of same-size units laid end to end"}]},{id:19,title:"The Kindness Chart",short:"Chart",parts:[{title:"Read the Chart",std:["1.MD.C.4"],n:3,dur:60,dir:"Look at the graph. Answer out loud.",fig:()=>F.barGraph({cats:["Watered","Carried","Read to"],vals:[9,4,7],max:10,step:1,title:"Kind things this week"}),qs:["How many kind things are on the whole graph?","Which kind thing happened the fewest times?","How many more people watered a row than carried something?"],key:["20 (9 + 4 + 7 = 20)","Carried, with 4","5 more (9 - 4 = 5)"],desc:"reading a graph with three categories: total, how many in each, and how many more"},{title:"Share It Fair",std:["1.G.A.3"],n:3,dur:60,dir:"Look at the three pictures. Answer out loud.",fig:()=>F.row(shareFig()),qs:["Which picture shows a loaf cut into halves, A or C?","Picture B is a garden bed cut into four equal parts. What do you call one of those parts?","Is picture C cut into halves? Why or why not?"],key:["A. One line down the middle, and the two pieces are the same size","A fourth, or a quarter. A fourth of the bed, or one quarter of the bed, both count","No. The two pieces are not the same size, and halves have to be equal shares"],desc:"halves and fourths of circles and rectangles, and equal shares"}]},{id:20,title:"Copy a Butterfly",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A butterfly has a long thin tongue. It rolls up like a spring. It does that when not in use. It unrolls it and reaches down. It goes all the way down. The throat of a flower is narrow. The sweet drop is at the bottom.</p>
     <div class="figure">${ic("butterfly",104)}${ic("tulip",88)}</div>
     <p class="big">The garden shed has a jar. It is tall and narrow. The last plant food is in there. It sits at the bottom. No hand or spoon will reach it.</p>`,qs:["How does a long thin tongue get a butterfly to food that a short wide mouth could never reach?","Draw a tool that copies the butterfly's long thin tongue and gets the plant food out of the tall jar.","Tell me which animal part you copied and how the shape of your tool reaches the bottom."],key:["It is thin enough to fit down a narrow opening and long enough to reach the bottom. Any answer about being long and thin counts.","Any long thin tool: a straw, a thin tube, a long narrow spoon, a stick with a cup on the end, a pipe that sucks up liquid. A wide scoop is partial, so ask what the butterfly's tongue is like.","Needs both halves: names the long thin rolled tongue as the part copied, and says the narrow shape fits down the jar where a hand cannot go."]}]},{id:21,title:"Cat and Kittens",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"A cat has made a bed for her four kittens in a basket in the corner of the garden shed. The kittens are too young to see well. Whenever she comes back she sits down at the edge of the basket and makes a soft chirruping sound. Every time she makes it, all four kittens turn toward the sound and crawl to her. Before she lets them feed she licks each one all over, and the kittens stay still while she does it.",qs:["What do the kittens do every single time the cat makes her soft chirruping sound?","What does the cat do before she lets them feed?","The kittens cannot see well yet. How does the chirruping sound help them get to their parent?"],key:["They turn toward it and crawl to her. Every time is what makes it a pattern.","She licks each one all over, and they stay still for it.","They do not have to see her. They can hear where she is and go straight to the sound. Any answer about using sound instead of sight counts."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">Two tulips grown from seeds of the same parent plant. A kitten and the cat that is its parent.</p>
     <div class="figure">${ic("tulip",96)}${ic("purpleFlower",96)}</div>
     <div class="figure">${ic("catFace",88)}${ic("cat",112)}</div>`,qs:["These two tulips came from the same parent plant, but one is red and one is purple. Does that mean one of them is not a tulip? Say why.","Name one way both tulips are like the plant they came from.","The kitten has the same ears, whiskers and tail shape as its parent, but it is much smaller and its fur is a different color. Is that what you would expect from a young animal? Say why."],key:["No. Both are tulips. Plants grown from the same parent are like it, but not exactly like it, and not exactly like each other either.","Both have a stem, green leaves, and a cup shaped flower on top. Any likeness counts.","Yes. Young animals are like their parents in the big ways and different in smaller ways. The shape stays the same, the size and the color can be different."]}]},{id:22,title:"The Moon Walks East",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">At eight o'clock on four evenings a child in the garden wrote down where the moon was.</p>
     <table class="bigTable"><tr><th>Evening</th><th>Where the moon was at eight</th></tr>
     <tr><td>first evening</td><td>just over the garden gate</td></tr>
     <tr><td>second evening</td><td>a little to the left of the gate</td></tr>
     <tr><td>third evening</td><td>further to the left, over the shed</td></tr>
     <tr><td>fourth evening</td><td>further left still, over the big tree</td></tr></table>
     <div class="figure">${ic("moon",84)}${ic("tree",84)}${ic("star",84)}</div>`,qs:["Which way is the moon moving from one evening to the next?","On the fifth evening at eight o'clock, do you predict the moon will be over the big tree, or further to the left of it?","What in the log makes you confident enough to predict that?","The sun has come up over the far fence every morning this week. Is that a pattern too? Say why."],key:["To the left, a little more each evening.","further to the left of the big tree","It moved the same way by about the same amount on every one of the four evenings. A thing that repeats is a pattern, and a pattern lets you predict.","Yes. It happened the same way every morning, and anything that repeats like that can be predicted."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">How long there was enough daylight to work in the garden.</p>
     <table class="bigTable"><tr><th>Month</th><th>Hours of daylight</th></tr>
     <tr><td>February</td><td>11</td></tr><tr><td>May</td><td>14</td></tr>
     <tr><td>August</td><td>14</td></tr><tr><td>November</td><td>10</td></tr></table>`,qs:["Which month on the chart had the shortest amount of daylight?","Two months on the chart had the same number of hours. Which two?","A gardener wants to plant after school while it is still light. Should they choose February or May? Use the chart to say why."],key:["November, 10 hours","May and August, both 14 hours","May, because May has 14 hours of daylight and February has only 11. There are three more hours of light to work in."]}]},{id:23,title:"The Twanging Ruler",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have a ruler, try the first part. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Hold a ruler flat on a table with most of it sticking out over the edge. Press the end down and let it go.</p>
     <div class="figure">${ic("ruler",96)}${ic("pan",96)}</div>
     <p class="big">Now tear a tiny scrap of paper and lay it on an upturned pan. Hum a long low note very close to the pan without touching it.</p>`,qs:["What does the end of the ruler do, and what do you hear while it does it?","Catch the ruler in your hand. What happens to the sound, and why?","What does the paper scrap on the pan do while you hum?","Your humming never touched the paper. Say what moved the paper, and how."],key:["It shakes up and down very fast, and you hear a buzzing or twanging note while it moves.","The sound stops at once, because the ruler can no longer shake. No shaking, no sound.","It wobbles, jumps, or slides a little.","The humming made the air shake, the shaking air made the pan shake, and the shaking pan moved the paper. A sound can move a thing without touching it."]}]},{id:24,title:"The Dark Closet",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The closet by the back door has no window, and the door fits tightly.</p>
     <div class="figure">${ic("heart",96)}${ic("torch",96)}</div>`,qs:["A bright red paper heart is on a shelf inside the closed closet. Can you see it? Say why or why not.","What would you have to do before the paper heart could be seen?","Does a bright color help you see a thing when there is no light in the room at all? Say why."],key:["No. No light gets into the closet, and a thing can only be seen when light shines on it and comes back to your eyes.","Light has to reach it: a flashlight, a lamp, or the door opened to let light in.","No. A color is only something you see when light bounces off the thing. With no light, bright red and dull gray look the same, which is to say they cannot be seen at all."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">One flashlight beam was pointed at four things in the dark closet and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clear glass vase</td><td>went straight through</td></tr>
     <tr><td>a sheet of thin tissue paper</td><td>a soft pink glow came through</td></tr>
     <tr><td>a cardboard box</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>the back of a metal spoon</td><td>bounced off to the side</td></tr></table>`,qs:["Which thing stopped the beam and made a dark shadow?","Which thing let a soft glow through?","Hold the tissue paper in front of the flashlight and the light turns soft and pink. Why does it change like that?","Which two of the four would make the wall behind them darker? Say what each one did with the light."],key:["the cardboard box","the thin tissue paper","Some of the light goes through the paper and some is stopped, and the paper spreads what gets through. The paper's own color tints it.","The cardboard box and the metal spoon. The box stopped the light, and the spoon sent it off to the side. Both leave less light on the wall behind, for different reasons."]}]},{id:25,title:"Window to Window",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">Two friends live in houses. The houses are facing each other. A wide courtyard is across the middle. At bedtime both windows are shut. Neither one can hear the other call.</p>
     <div class="figure">${ic("cabin",88)}${ic("torch",88)}${ic("lamp",88)}</div>`,qs:["Draw a device for one window that tells the other window good night. It has to use light or sound.","Tell me about your drawing. Does it send light, or does it send sound?","Make up a second message your device could send, and say how the friend will tell the two apart."],key:["Any device that carries light or sound across the courtyard: a flashlight flashed at the window, a lamp switched on and off, a bell on a string, a card held up with a lamp behind it.","Names it and says which one it uses.","A second message with a clearly different signal: two flashes instead of one, a long flash, a different color, a different number of rings. The idea to listen for is that the signals must not be mixed up."]}]},{id:26,title:"Fix the Mixed Up Cards",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"Every seed packet in the garden shed has a card with its name and its planting date. All the cards live loose in one open box. When somebody carries the box out to the beds, the cards slide about and change places, and more than once the wrong seeds have gone into the wrong row.",qs:["What is the problem the gardeners want to change?","Ask me something about the problem that would help you work out a fix.","What would you count first, before you made a new box?"],key:["The cards slide about and get mixed up in the open box, so the wrong seeds go into the wrong row.","Any real question: how many cards are there, how big is the box, how far is it carried, are the cards all the same size, does it happen on the way out or on the way back. A statement is not a question, so ask once more.","Any real observation: count how many cards end up in the wrong place, watch what happens while the box is carried, see whether the box is too big for the cards."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw a better box or holder for the cards, one that keeps them in order while it is carried.</p>
     <div class="figure">${ic("box",88)}${ic("books",88)}${ic("sprout",88)}</div>`,qs:["Draw your new holder.","Point to the part that keeps each card in its place and tell me its shape.","Tell me why that shape keeps the order better than one open box does."],key:["Any real fix: a tray with a divider between each card, slots for each card, a ring through a hole in every card, pockets, a lid with a clip, cards taped to a board in order.","Names a shape: upright walls between the cards, narrow slots, a ring, a row of pockets.","Because each card has its own place it cannot slide out of. In one open box there is nothing to keep two cards apart."]}]},{id:27,title:"Which Tray Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two card holders were carried out to the beds and back, twelve cards in each, five trips each.</p>
     <table class="bigTable"><tr><th>Holder</th><th>Cards out of order at the end, out of 12</th></tr>
     <tr><td>a tray with dividers</td><td>0</td></tr>
     <tr><td>a bag with a drawstring</td><td>9</td></tr></table>`,qs:["Which one kept the cards in order better?","What do the two numbers in the chart tell you?","The two holders carried the same number of cards on the same number of trips. Why does that matter when you compare them?"],key:["the tray with dividers","No cards were out of order in the tray, 0 out of 12, and 9 out of 12 were out of order in the bag. The numbers have to be in the answer.","Because then the only difference is the holder itself. If one had carried three cards and the other twelve, the test would not tell you which holder is better."]}]},{id:28,title:"Sharing the Garden Bench",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility, and explaining why rules exist for places everybody shares",read:"There is one long bench in the school garden and everybody is allowed to use it. Two classes wanted it at the same time, so they made an agreement. Anybody may sit on the bench. If the bench is full, you wait or you make room. Whoever sits on it last takes the cups and the tools back inside. The two classes did not agree at first. One class wanted the bench every lunchtime. They listened to each other anyway, and nobody was shouted down.",qs:["Anybody may sit on the bench. Is being allowed to sit there a right or a responsibility?","Taking the cups and tools back inside is a job. Is that a right or a responsibility?","Making room for somebody who is waiting is not in a rule book, but it is a kind of responsibility. Who does it help?","The two classes did not agree at first, and they listened to each other anyway. Why does a person have a right to say what they think even when the other people disagree with them?"],key:["a right","a responsibility","Everybody, including the person waiting, and the person making room, because next time it may be them waiting. Any answer about the whole group counts.","Because everybody has that right, so if you shout somebody down today your own turn can be taken away tomorrow, and the group cannot find a fair answer without hearing everybody first. Accept any answer about respecting other people’s opinions or about everybody getting a turn to speak. (HSS-1.1)"]}]},{id:29,title:"The Garden Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the school garden, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("tree",56)}</td><td></td><td>${ic("cabin",56)}</td></tr>
     <tr><th>B</th><td>${ic("tulip",56)}</td><td>${ic("tulip",56)}</td><td>${ic("tulip",56)}</td></tr>
     <tr><th>C</th><td>${ic("drop",56)}</td><td>${ic("heart",56)}</td><td></td></tr></table>
     <p class="big">${ic("tree",48)} the shade tree &nbsp; ${ic("cabin",48)} the garden shed &nbsp; ${ic("tulip",48)} the flower beds &nbsp; ${ic("drop",48)} the water barrel &nbsp; ${ic("heart",48)} the kindness bench</p>
     <p class="big">The top of this map is north. The bottom is south, the right is east, and the left is west.</p>
     <p class="big">The little pictures down the side are this map’s symbols. The list that tells you what each one means is called the map key.</p>`,qs:["Find the kindness bench. Give its exact spot on the grid, the letter and the number.","Where is the garden shed compared to the kindness bench? Use north, south, east or west.","Name one natural thing and one built thing on this map.","If you drew a map of your own yard or your own classroom, name one symbol you would use and say what it would stand for. Then say which side of your map you would mark north."],key:["C2. Both parts are needed.","North of the bench and east of it. Both directions are needed for a full answer, and north east counts.","Needs both halves. Nature: the shade tree. Built: the garden shed, the water barrel, the kindness bench. The flower beds may be argued either way if the student explains that people dug them and the flowers grow.","Any workable symbol with its meaning given, such as a little square for a desk, a wavy line for a sink, a tree shape for the tree outside. For the second part, any one side named as north, as long as the student says the other three would then be south, east and west, or points to them. (HSS-1.2)"]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">Each family helps in this garden. Each one planted one thing. They grew up eating it. There are nine different plants. They are in the beds. No two families chose the same one.</p>
     <div class="figure">${ic("herb",88)}${ic("carrot",88)}${ic("corn",88)}</div>`,qs:["Nine families planted nine different things. What does that tell you about where those families came from?","Name three places in your own town that people built, and say which one you go to most often.","Name one kind thing you could do for a family that has just moved to your town from far away."],key:["They came from different places and grew up with different food. Any answer about different backgrounds counts.","Any three built places, with one named as most visited: a school, a store, a park, a library, a playground, a bus stop.","Any real kindness: say hello, show them the way to school, ask them to play, learn to say their name correctly, tell them where the park is."]}]},{id:30,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling why a country makes lasting symbols and naming one the student has seen",html:()=>`<p class="big">Four presidents have their faces carved. The faces are in a mountain side. It is in South Dakota. The carving is called Mount Rushmore. It took fourteen years to make.</p>
     <div class="figure">${ic("mountain",104)}${ic("flag",96)}</div>`,qs:["What is carved into the side of the mountain at Mount Rushmore?","It took fourteen years of work. Why would people spend that long carving faces into a mountain?","Name one symbol of the United States that you have seen with your own eyes, and say where you saw it."],key:["The faces of four presidents.","So the country would remember those people for a very long time. Stone lasts, and a symbol is meant to last. Any answer about remembering counts.","Any real answer with a place: a flag at school, a flag on a post office, an eagle on a coin, a flag on a stamp, a flag outside a fire station."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Sending a kind note to someone far away.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>how the note traveled</td><td>a rider on a horse carried the bag</td><td>a message on a screen</td></tr>
     <tr><td>how long it took</td><td>several days</td><td>a second</td></tr>
     <tr><td>why people sent it</td><td>to tell someone they were thinking of them</td><td>to tell someone they were thinking of them</td></tr>
     <tr><td>a game children played</td><td>marbles, jump rope, a hoop rolled with a stick</td><td>a game on a screen, and still jump rope</td></tr></table>
     <div class="figure">${ic("horse",88)}${ic("phone",88)}</div>`,qs:["Long ago, who carried a note to someone far away?","How does a note get there today?","Look at the games row. Name one game children played long ago that hardly anybody plays now, and one game children still play today.","Which part of this is still true today, just as it was then?"],key:["A rider on a horse, carrying the bag of letters.","On a screen, as a message.","Hardly played now: marbles, or rolling a hoop with a stick. Still played: jump rope. Both parts are what is being checked, because games are one of the things this standard asks you to compare. (HSS-1.4)","Why people sent it: to tell someone they were thinking of them. That is the half of the standard that is easy to miss, so it is asked on its own."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Longer Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["greenhouse","unkind","kindest"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["greenhouse (two syllables, compound word, ee team and ou team)","unkind (prefix un-)","kindest (suffix -est)"]},4:{id:"L4",lv:true,title:"Level Up: The Tool Shed",std:["RF.2.4"],needs:["RF.1.4"],n:66,label:"words read correctly",dir:"Read this harder story out loud in your best reading voice.",html:()=>`<p class="passage">${TOOLS}</p>`,key:["66 words. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace and expression. A grade 2 reader should group the words into phrases, not read one word at a time.","Quick check after reading: Why does the list have a second line now? (a rake went missing for a month, so now you also write the day you bring the tool back)"]},5:{id:"L5",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The club had 42 paper hearts in the box. Somebody brought 29 more. Then the club hung 23 of them on the string. How many hearts are still in the box?</p>`,key:["48 hearts (42 + 29 = 71, then 71 - 23 = 48)"]},6:{id:"L6",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${SHED}</p><ol class="qlist"><li>Why could Ines not get the trowel at first?</li><li>How did Dev solve the problem?</li></ol>`,key:["It sat on the top shelf, too high for her to reach, even stretched up on her toes","He went and got the step stool that was kept behind the door, then steadied it so she could climb up and reach"]},8:{id:"L8",lv:true,title:"Level Up: Add It Both Ways",std:["2.NBT.B.5"],needs:["1.NBT.C.4"],n:3,dir:"Solve each one on your paper. Show your work and hold it up.",html:()=>`<ol class="qlist"><li>38 + 47</li><li>72 - 35</li><li>56 + 29</li></ol>`,key:["85 (38 + 47 = 85)","37 (72 - 35 = 37)","85 (56 + 29 = 85)"]},9:{id:"L9",lv:true,title:"Level Up: Five Minutes at a Time",std:["2.MD.C.7"],needs:["1.MD.B.3"],n:3,dir:"Look at the clocks. Say or write each answer.",html:()=>`<div class="figure">${F.clock(2,15,200)}${F.clock(9,45,200)}</div><ol class="qlist"><li>What time does the first clock say?</li><li>What time does the second clock say?</li><li>The club works in the garden at 10:00 in the morning. Write that time with a.m. or p.m.</li></ol>`,key:["2:15, said as two fifteen or quarter past two. The long hand is on the 3, and one number mark is five minutes","9:45, said as nine forty-five or quarter to ten. The long hand is on the 9, which is 45 minutes. Watch for ten forty-five, because the short hand is almost on the 10","10:00 a.m. Morning is before noon, so it is a.m."]}};const PASSAGE_STD=["RL.1.1","RI.1.1","RL.2.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["The better way is ____.","I think ____.","I picked it because ____.","That is what I think."],facts:["One way to help is ____.","First you need ____.","Then you ____.","That is how you ____."],story:["One day, ____.","First, ____.","Then, ____.","It felt ____."]};function sentHtml(st){const wk=st&&st.parts&&st.parts[0]&&st.parts[0].wk||"facts";return`<ul class="starters">${(STARTERS[wk]||STARTERS.facts).map(x=>`<li>${x}</li>`).join("")}</ul>`}let tpsBlk=[0,0];function tpsBlkHtml(){return`<div class="blk-row"><button class="chip" data-tb="0" data-td="1">Add a ten</button><button class="chip" data-tb="0" data-td="-1">Take a ten</button><button class="chip" data-tb="1" data-td="1">Add a one</button><button class="chip" data-tb="1" data-td="-1">Take a one</button><button class="chip" data-tb="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]?F.tens(tpsBlk[0],tpsBlk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} tens and ${tpsBlk[1]} ones on the mat.</p>`}function tpsBlkBind(b,r){b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{if(x.dataset.tb==="x")tpsBlk=[0,0];else{const i=+x.dataset.tb;tpsBlk[i]=Math.max(0,Math.min(i?19:9,tpsBlk[i]+ +x.dataset.td))}r()})}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:96,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS_UI={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:tpsBlkHtml,bind:tpsBlkBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.A.1"],msg:"With the number line a student can count every hop instead of using a strategy. Note whether the answer came from counting or from knowing the fact."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart shows the numerals, so counting, reading, and writing numbers with it open is supported, not independent."},{t:"chart",std:["1.NBT.C.4"],msg:"On the 120 chart a student can hop down a column to add a ten. Note whether the answer came from the chart or from knowing the tens."},{t:"tf",std:["1.NBT.B.2"],msg:"Ten frames show the bundles of ten for the student. Note it if the tens and ones were read off the frames rather than said from the number."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.1","W.1.2","W.1.3","W.1.8"],msg:"If an adult wrote the words for the student, note it. The writing checks still count, but the printing does not."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS_UI,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
